(async () => {
  const THREE = await import('/vendor/three/three.module.js');
  const { Field } = await import('/src/world/field.js');
  const rc = new THREE.Raycaster();
  const O = new THREE.Vector3(), T = new THREE.Vector3(), D = new THREE.Vector3();
  const IGNORE = /^(ground|water|sky|tufts|flowers|motes|contactShadows|grass|shadow)/i;
  const opaqueOf = (o, hg) => {
    if (!o.visible) return false;
    for (let a = o; a; a = a.parent) {
      if (a === hg) return false;
      const n = (a.name || '') + '<' + ((a.parent && a.parent.name) || '') + '>';
      if (IGNORE.test(a.name || '') || IGNORE.test(n)) return false;
    }
    const m = o.material, mats = Array.isArray(m) ? m : [m];
    return mats.reduce((x, mm) => Math.max(x, (mm && mm.transparent) ? (mm.opacity != null ? mm.opacity : 1) : 1), 0) >= 0.6;
  };
  const sample = (S) => {
    const w = Field.world(); if (!w || !w.player || !w.player.hero) return;
    const cam = w.camera, hg = w.player.hero.group, h = w.player.hero.height || 1.11, p = hg.position;
    O.copy(cam.position); T.set(p.x, p.y + h * 0.62, p.z); D.copy(T).sub(O);
    const far = D.length() - 0.08; if (far <= 0.05) return;
    D.normalize(); rc.camera = cam; rc.set(O, D); rc.far = far; rc.near = 0.01;
    let hits = []; try { hits = rc.intersectObject(w.scene, true); } catch (e) { S.errs++; return; }
    let blocker = null;
    for (const it of hits) {
      const o = it.object;
      if (!opaqueOf(o, hg)) continue;
      blocker = { name: (o.name || 'mesh') + (o.isInstancedMesh ? '[inst]' : '') + '<' + ((o.parent && o.parent.name) || '?') + '>' };
      break;
    }
    S.n++;
    if (blocker) {
      S.blocked++; S.who[blocker.name] = (S.who[blocker.name] || 0) + 1;
      const k = __DQ.cameraSight();
      if (!k.clear) { S.solid++; S.swho[blocker.name] = (S.swho[blocker.name] || 0) + 1; }
      else { S.ghost++; }
    }
  };
  const run = (label, plan, every = 2) => {
    const S = { label, n: 0, blocked: 0, solid: 0, ghost: 0, who: {}, swho: {}, errs: 0 };
    __DQ.freeze(true);
    for (const [btn, ticks] of plan) {
      if (btn && btn !== 'wait' && btn !== 'orbit') __DQ.hold(btn, ticks * 16.6667);
      for (let i = 0; i < ticks; i++) {
        if (btn === 'orbit') { const w = Field.world(); if (w) w.cameraRig.orbit((i / ticks) * 360, false); }
        __DQ.advance(16.6667);
        if (i % every === 0) try { sample(S); } catch (e) { S.errs++; }
      }
    }
    __DQ.freeze(false);
    const r3 = v => +Number(v).toFixed(3);
    return { label, samples: S.n, heroHiddenPct: S.n ? r3(100 * S.blocked / S.n) : 0,
      heroHiddenSolidPct: S.n ? r3(100 * S.solid / S.n) : 0,
      ghostPct: S.n ? r3(100 * S.ghost / S.n) : 0,
      solidBy: Object.entries(S.swho).sort((a,b)=>b[1]-a[1]).slice(0,5),
      blockedBy: Object.entries(S.who).sort((a,b)=>b[1]-a[1]).slice(0,5), errs: S.errs };
  };
  window.__KEEP = run('puddlewick-walk', [['up',120],['right',120],['down',120],['left',120]]);
  return JSON.stringify(window.__KEEP);
})()
